package dev.steelcode.core;

import dev.steelcode.core.api.CoreRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * SteelCodeCore: a multiloader (Fabric + NeoForge) library to create blocks, items and gameplay features from
 * common code, with every JSON generated by datagen.
 * <pre>{@code
 * public static final CoreRegistry REG = SteelCodeCore.registry("mymod");
 * }</pre>
 * Start at {@link CoreRegistry}. Packages:
 * <ul>
 *     <li>{@code dev.steelcode.core.api} – the registry and its builders, grouped by topic.</li>
 *     <li>{@code dev.steelcode.core.content} – block, item and entity classes you may reuse or extend.</li>
 *     <li>{@code dev.steelcode.core.impl} – implementation details; not API, may change at any time.</li>
 * </ul>
 */
public final class SteelCodeCore {

    /** The library's own mod id, {@code "steelcodecore"}. */
    public static final String MOD_ID = "steelcodecore";
    /** The library logger. */
    public static final Logger LOGGER = LoggerFactory.getLogger("SteelCodeCore");

    private SteelCodeCore() {
    }

    /**
     * Creates the registry of your mod. Call it once per mod, in a static field of your common code.
     * @param modId your mod id
     * @return a new registry
     */
    public static CoreRegistry registry(String modId) {
        return CoreRegistry.create(modId);
    }

    /** Internal: common initialization of the library, called by each loader's entrypoint. */
    public static void init() {
        LOGGER.debug("SteelCodeCore loaded");
    }
}
